function ringPts(r) {
  const pts = [];
  for (let c = 15; c <= 33; c += 2) pts.push([r, c, (c % 4 === 1) ? 'W' : 'X']);
  for (let c = 16; c <= 34; c += 2) pts.push([r + 1, c, (c % 4 === 0) ? 'X' : 'W']);
  return pts;
}
