// GOLD with a rising aura, settling into the transformed idle. goldHairOf is
// zone-bounded because the hair letters (E/F) are also the eye pupils — never
// remap them globally.
function goldHairOf(grid, hd = 0) {
  const map = { E:'W', F:'V', G:'U', H:'X' };
  return grid.map((row, r) => row.map((v, c) => {
    if (!v) return v;
    const rr = r - hd;
    const topBlock = rr >= 4 && rr <= 6 && c >= 21 && c <= 33;
    const leftTwist = c >= 19 && c <= 20 && rr >= 5 && rr <= 16;   // the face twist
    const rightTwist = c >= 30 && c <= 33 && rr >= 5 && rr <= 17;
    if ((topBlock || leftTwist || rightTwist) && map[v]) return map[v];
    // thin hair shapes are ALL outline after the auto-outline pass — the letter
    // remap never sees them, so convert the outline cells themselves:
    if (v === 'e') {
      if (rr === 4 && c >= 22 && c <= 32) return 'V';               // spike tips
      if (rr >= 5 && rr <= 6 && c >= 22 && c <= 32) return 'U';     // block grooves
      if (leftTwist) return 'V';                                    // face twist body
    }
    return v;
  }));
}
